    html: '<div class="middle">\n<div class="left_block">\n<div class="menu">\n<ul class="menu"><li class="level1"><a href="/" title="Главная страница">Главная</a></li>\n<li class="level1"><a href="/about.html" title="О компании">О компании</a></li>\n<li class="level1"><a href="/services.html" title="Услуги">Услуги</a></li>\n<li class="level1"><a href="/portfolio.html" title="Портфолио">Портфолио</a></li>\n<li class="level1 active self"><a href="/documentation.html" title="Документация">Документация</a><ul><li class="level2"><a href="/documentation/extjs.html" title="ExtJS">ExtJS</a></li>\n</ul></li>\n<li class="last level1"><a href="/contacts.html" title="Контактная  информация">Контактная  информация</a></li>\n</ul> </div>\n</div>\n<div class="center_block">\n<div class="breadcrumbs"><span class="B_crumbBox"><span class="B_firstCrumb"><a href="/">Главная</a></span> » <h1 class="B_lastCrumb" tabindex="-1"><span class="B_currentCrumb">Документация</span></h1></span></div>\n<div id="content"><p> <ul class="menu"><li class="level1"><a href="/documentation/extjs.html" title="ExtJS">ExtJS</a><ul><li class="level2"><a href="/documentation/extjs/extjs_lessons.html" title="Уроки ExtJS">Уроки ExtJS</a><ul><li class="level3"><a href="/documentation/extjs/extjs_lessons/lesson1.html" title="ExtJS. Урок первый. Демонстрирует работу библиотеки ExtJS">ExtJS. Урок первый. Демонстрирует работу библиотеки ExtJS</a></li>\n<li class="level3"><a href="/documentation/extjs/extjs_lessons/lesson2.html" title="ExtJS. Урок 2. Окна. Ext.Window">ExtJS. Урок 2. Окна. Ext.Window</a></li>\n<li class="level3"><a href="/documentation/extjs/extjs_lessons/lesson3.html" title="ExtJS. Урок 3. Окна, часть вторая. Ext.Window, Ext.Toolbar">ExtJS. Урок 3. Окна, часть вторая. Ext.Window, Ext.Toolbar</a></li>\n<li class="level3"><a href="/documentation/extjs/extjs_lessons/lesson4.html" title="ExtJS. Урок 4. Окна. Изменение размеров и другие свойства окон. Ext.Window properties">ExtJS. Урок 4. Окна. Изменение размеров и другие свойства окон. Ext.Window properties</a></li>\n<li class="level3"><a href="/documentation/extjs/extjs_lessons/lesson5.html" title="ExtJS. Урок 5. Хранилища и таблицы. Ext.grid, Ext.data.Store">ExtJS. Урок 5. Хранилища и таблицы. Ext.grid, Ext.data.Store</a></li>\n<li class="level3"><a href="/documentation/extjs/extjs_lessons/lesson6.html" title="ExtJS. Урок 6. Экспериментируем с шаблонами элементов.  Ext.Template">ExtJS. Урок 6. Экспериментируем с шаблонами элементов.  Ext.Template</a></li>\n<li class="last level3"><a href="/documentation/extjs/extjs_lessons/examples.html" title="Редирект на реальную страницу">Редирект на реальную страницу</a></li>\n</ul></li>\n<li class="level2"><a href="/ExtJS/docs" rel="noopener noreferrer" target="_blank" title="Документация по ExtJS">Документация по ExtJS</a></li>\n<li class="last level2"><a href="/ExtJS/examples" rel="noopener noreferrer" target="_blank" title="Примеры ExtJS">Примеры ExtJS</a></li>\n</ul></li>\n</ul> </p></div>\n</div>\n<div class="clear"></div>\n</div>',
